class Student {
    private int id;
    private String name;
    private int age;
    private int marks;
    private String college;
    public void setId(int id) {
        if (id > 0) {
            this.id = id;
        } else {
            System.out.println("Invalid ID");
        }
    }
    public int getId() {
        return id;
    }
    public void setName(String name) {
        if (name != null && name.length() >= 3) {
            this.name = name;
        } else {
            System.out.println("Invalid name");
        }
    }
    public String getName() {
        return name;
    }
    public void setAge(int age) {
        if (age > 18) {
            this.age = age;
        } else {
            System.out.println("Invalid age");
        }
    }
    public int getAge() {
        return age;
    }
    public void setMarks(int marks) {
        if (marks > 20) {
            this.marks = marks;
        } else {
            System.out.println("Invalid marks");
        }
    }
    public int getMarks() {
        return marks;
    }
    public void setCollege(String college) {
        this.college = college;
    }
    public String getCollege() {
        return college;
    }
    public void study() {
        System.out.println("Student is studying");
    }
}
public class StudentApp {
    public static void main(String[] args) {
        Student student = new Student();
        student.setId(10);
        student.setName("Rommel");
        student.setAge(25);
        student.setMarks(90);
        student.setCollege("StringStack Institute of Technology");
        System.out.println(student.getId());
        System.out.println(student.getName());
        System.out.println(student.getAge());
        System.out.println(student.getMarks());
        System.out.println(student.getCollege());
        student.study();
    }
}

class Product {
    private int id;
    private String name;
    private double price;
    private int stock;
    private String description;
    public Product(int id, String name, double price, int stock, String description) {
        this.id = id;
        this.name = name;
        this.price = price;
        this.stock = stock;
        this.description = description;
    }
    public int getId() {
        return id;
    }
    public String getName() {
        return name;
    }
    public double getPrice() {
        return price;
    }
    public int getStock() {
        return stock;
    }
    public String getDescription() {
        return description;
    }
}
public class ProductApp {
    public static void main(String[] args) {
        Product product = new Product(
            10, "Laptop", 2000.0, 5, "Portable computer"
        );
        System.out.println(product.getId());
        System.out.println(product.getName());
        System.out.println(product.getPrice());
        System.out.println(product.getStock());
        System.out.println(product.getDescription());
    }
}

class Car {
    // No constructor is declared in this class.
}
public class DefaultConstructorDemo {
    public static void main(String[] args) {
        Car car = new Car();
        System.out.println("Car object created");
    }
}

